import { useState, useEffect, useRef } from "react";
import { supabase } from "./utils/supabase";

const C = {
  cream:   "#EDE8C8",
  navy:    "#1B2E4B",
  orange:  "#E07A20",
  white:   "#FFFFFF",
  muted:   "#A89F7A",
};

const injectFonts = () => {
  if (document.getElementById("ng-fonts")) return;
  const l = document.createElement("link");
  l.id = "ng-fonts"; l.rel = "stylesheet";
  l.href = "https://fonts.googleapis.com/css2?family=Caveat:wght@600;700&family=Syne:wght@400;600;700;800&family=DM+Sans:wght@300;400;500&display=swap";
  document.head.appendChild(l);
};

const PRODUTOS = [
  { id:1, titulo:"Don't Tap the Glass",       subtitulo:"Tyler The Creator",              preco:140, bg:"#2a1a1a", emoji:"🎨", accent:"#c0392b" },
  { id:2, titulo:"Devorador de Mundos",        subtitulo:"Galactus | Quarteto Fantástico", preco:140, bg:"#120830", emoji:"🌌", accent:"#7b2fff" },
  { id:3, titulo:"Vagabundo de Luxo",          subtitulo:"Wiu",                            preco:140, bg:"#8b0000", emoji:"💎", accent:"#e07a20" },
  { id:4, titulo:"Um Banho Laranja",           subtitulo:"",                               preco:140, bg:"#1a2a0a", emoji:"🍊", accent:"#e07a20" },
  { id:5, titulo:"Guerreiro Cósmico",          subtitulo:"Arte Original",                  preco:160, bg:"#0a1628", emoji:"⚡", accent:"#00bfff" },
  { id:6, titulo:"Rei das Ruas",               subtitulo:"Edição Limitada",                preco:160, bg:"#1a1a1a", emoji:"👑", accent:"#ffd700" },
  { id:7, titulo:"Fluxo Urbano",               subtitulo:"Arte Digital",                   preco:140, bg:"#0d2b1a", emoji:"🌿", accent:"#2ecc71" },
  { id:8, titulo:"Neon Dreams",                subtitulo:"Arte Original",                  preco:180, bg:"#1a0a28", emoji:"🔮", accent:"#ff00ff" },
];

const OPCOES_QUADRO = [
  { id:"sem",     label:"Quadro Normal",      desc:"Impressão sem moldura",                        extra:0  },
  { id:"borda",   label:"Com Borda",           desc:"Moldura simples preta",                        extra:20 },
  { id:"vidro",   label:"Com Vidro",           desc:"Proteção em vidro cristal",                    extra:40 },
  { id:"bv",      label:"Borda + Vidro",       desc:"Moldura + vidro protetor",                     extra:60 },
  { id:"premium", label:"Premium Completo",    desc:"Moldura dourada + vidro + passe-partout",      extra:90 },
];

const TAMANHOS = [
  { id:"p",  label:"P",  desc:"20×30cm", extra:0   },
  { id:"m",  label:"M",  desc:"30×40cm", extra:30  },
  { id:"g",  label:"G",  desc:"40×60cm", extra:60  },
  { id:"gg", label:"GG", desc:"60×90cm", extra:100 },
];

/* ── helpers de estilo ── */
const btnIcon = () => ({ background:"none", border:"none", cursor:"pointer", color:C.navy, display:"flex", alignItems:"center", justifyContent:"center", position:"relative", padding:4 });
const qtyBtn  = () => ({ width:28, height:28, border:"1px solid #ddd", background:"transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", fontSize:16, color:C.navy });

const fmt = v => v.toLocaleString("pt-BR", { style:"currency", currency:"BRL" });

const IMG_BANNER = "data:image/jpeg;base64,";

/* ════════════════════════════════════════════════════════════ */
export default function NandyGovi({ onCheckout, onIrCadastro }) {
  injectFonts();

  const [cart, setCart]         = useState([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [modal, setModal]       = useState(null);
  const [opcao, setOpcao]       = useState("sem");
  const [tamanho, setTamanho]   = useState("m");
  const [toast, setToast]       = useState("");
  const [tick, setTick]         = useState(0);
  const [usuario, setUsuario]         = useState(null);
  const [perfilOpen, setPerfilOpen]   = useState(false);
  const [menuOpen, setMenuOpen]       = useState(false);
  const [categoriaAtiva, setCatAtiva] = useState(0);
  const [produtos, setProdutos]       = useState([]);
  const [loadingProd, setLoadingProd] = useState(true);

  const CATEGORIAS = ["Todos","Natureza","Abstrato","Urbano","Minimalista","Retrô"];

  useEffect(() => {
    const id = setInterval(() => setTick(t => t - 1), 22);
    return () => clearInterval(id);
  }, []);

  // Ouve sessão do Supabase
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUsuario(session?.user ?? null);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_e, session) => {
      setUsuario(session?.user ?? null);
    });
    return () => subscription.unsubscribe();
  }, []);

  // Carrega produtos do Supabase
  useEffect(() => {
    supabase.from("produtos").select("*").eq("ativo", true).order("criado_em", { ascending: false })
      .then(({ data, error }) => {
        if (error) console.error("Erro ao carregar produtos:", error);
        setProdutos(data || []);
        setLoadingProd(false);
      });
  }, []);

  const tickTxt = "Enviamos para todo o Brasil!  ·  Visuais brutalistas de um simples artista.  ·  Visite o meu portfólio clicando aqui!  ·  ";
  const cartTotal = cart.reduce((s,c) => s + c.preco * c.qty, 0);
  const cartCount = cart.reduce((s,c) => s + c.qty, 0);

  function openModal(p) { setOpcao("sem"); setTamanho("m"); setModal(p); }

  function addToCart(produto, op, tam) {
    const opc_ = OPCOES_QUADRO.find(o => o.id === op);
    const tam_ = TAMANHOS.find(t => t.id === tam);
    const preco = Number(produto.preco_base || produto.preco || 0) + (opc_?.extra||0) + (tam_?.extra||0);
    const key   = `${produto.id}-${op}-${tam}`;
    setCart(prev => {
      const ex = prev.find(c => c.key === key);
      if (ex) return prev.map(c => c.key === key ? { ...c, qty: c.qty+1 } : c);
      return [...prev, { key, produto, opc: opc_, tam: tam_, preco, qty:1 }];
    });
    showToast(`"${produto.titulo}" adicionado!`);
    setModal(null);
  }

  function removeItem(key) { setCart(prev => prev.filter(c => c.key !== key)); }
  function changeQty(key, d) {
    setCart(prev => prev.map(c => c.key===key ? { ...c, qty: Math.max(0, c.qty+d) } : c).filter(c => c.qty > 0));
  }

  function showToast(msg) { setToast(msg); setTimeout(() => setToast(""), 3000); }

  const opc_  = OPCOES_QUADRO.find(o => o.id === opcao);
  const tam_  = TAMANHOS.find(t => t.id === tamanho);
  const modalPreco = modal ? Number(modal.preco_base || modal.preco || 0) + (OPCOES_QUADRO.find(o=>o.id===opcao)?.extra||0) + (TAMANHOS.find(t=>t.id===tamanho)?.extra||0) : 0;

  /* ── RENDER ── */
  return (
    <div style={{ fontFamily:"'DM Sans',sans-serif", background:C.cream, color:C.navy, overflowX:"hidden", minHeight:"100vh" }}>

      {/* TICKER */}
      <div style={{ background:C.navy, color:C.cream, fontSize:12, padding:"9px 0", overflow:"hidden", whiteSpace:"nowrap" }}>
        <span style={{ display:"inline-block", transform:`translateX(${tick % (tickTxt.length*8)}px)`, letterSpacing:"0.06em" }}>
          {tickTxt.repeat(6)}
        </span>
      </div>

      {/* HEADER */}
      <header style={{ background:C.cream, borderBottom:`1px solid ${C.muted}44`, position:"sticky", top:0, zIndex:100, isolation:"isolate" }}>
        <div style={{ maxWidth:1280, margin:"0 auto", padding:"0 24px", display:"flex", alignItems:"center", justifyContent:"space-between", height:68 }}>

          {/* logo */}
          <a href="#" style={{ textDecoration:"none", display:"flex", alignItems:"flex-end", gap:2, flexShrink:0 }}>
            <span style={{ fontFamily:"'Syne',sans-serif", fontSize:24, fontWeight:800, color:C.navy, letterSpacing:"0.02em", lineHeight:1 }}>NANDY</span>
            <span style={{ fontFamily:"'Caveat',cursive", fontSize:26, color:C.orange, lineHeight:1, marginBottom:2 }}>Govi</span>
          </a>

          {/* nav desktop — oculto no mobile */}
          <nav style={{ display:"flex", gap:28 }} className="ng-desktop-nav">
            {["Início","Sobre","Instagram","TikTok"].map(n => (
              <a key={n} href="#" style={{ fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:600, color:C.navy, textDecoration:"none", letterSpacing:"0.04em" }}
                onMouseOver={e=>e.target.style.color=C.orange} onMouseOut={e=>e.target.style.color=C.navy}>{n}</a>
            ))}
          </nav>

          {/* ações direita */}
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>

            {/* busca — oculto no mobile */}
            <div style={{ display:"flex", alignItems:"center", gap:8, background:C.white, border:`1px solid ${C.muted}44`, padding:"7px 12px" }} className="ng-desktop-search">
              <input placeholder="Buscar" style={{ border:"none", outline:"none", fontFamily:"'DM Sans',sans-serif", fontSize:13, background:"transparent", width:120, color:C.navy }}/>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            </div>

            {/* botão perfil */}
            <button onClick={() => usuario ? setPerfilOpen(p => !p) : onIrCadastro?.()}
              style={{ ...btnIcon(), position:"relative" }} title={usuario ? "Minha conta" : "Entrar"}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
              {usuario && <span style={{ position:"absolute", bottom:-2, right:-2, width:8, height:8, borderRadius:"50%", background:"#22C55E", border:"1.5px solid #fff" }}/>}
            </button>

            {/* dropdown perfil */}
            {perfilOpen && usuario && (
              <div style={{ position:"absolute", top:62, right:54, background:"#fff", border:`1px solid ${C.muted}33`, boxShadow:"0 8px 32px rgba(0,0,0,.15)", zIndex:300, minWidth:200, padding:"8px 0" }}
                onMouseLeave={() => setPerfilOpen(false)}>
                <div style={{ padding:"12px 16px 10px", borderBottom:`1px solid ${C.muted}22` }}>
                  <p style={{ fontSize:12, fontWeight:700, color:C.navy, margin:0 }}>{usuario.user_metadata?.nome || "Minha conta"}</p>
                  <p style={{ fontSize:11, color:C.muted, margin:"3px 0 0" }}>{usuario.email}</p>
                </div>
                <button onClick={async () => { await supabase.auth.signOut(); setPerfilOpen(false); }}
                  style={{ width:"100%", padding:"10px 16px", background:"none", border:"none", textAlign:"left", cursor:"pointer", fontSize:13, color:"#DC2626", fontFamily:"'DM Sans',sans-serif" }}>
                  Sair da conta
                </button>
              </div>
            )}

            {/* carrinho */}
            <button style={btnIcon()} onClick={() => setCartOpen(true)}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
              {cartCount > 0 && <span style={{ position:"absolute", top:-6, right:-6, background:C.orange, color:"#fff", borderRadius:"50%", width:18, height:18, fontSize:10, display:"flex", alignItems:"center", justifyContent:"center", fontWeight:700 }}>{cartCount}</span>}
            </button>

            {/* hamburguer — só mobile */}
            <button onClick={() => setMenuOpen(o => !o)} className="ng-hamburger"
              style={{ background:"none", border:"none", cursor:"pointer", padding:6, display:"none", flexDirection:"column", gap:5, alignItems:"center", justifyContent:"center" }}>
              <span style={{ display:"block", width:22, height:2, background:menuOpen ? "transparent" : C.navy, transition:"all .25s", transform: menuOpen ? "none" : "none" }}/>
              <span style={{ display:"block", width:22, height:2, background:C.navy, transition:"all .25s",
                transform: menuOpen ? "rotate(45deg) translate(5px, 5px)" : "none" }}/>
              <span style={{ display:"block", width:22, height:2, background:C.navy, transition:"all .25s",
                transform: menuOpen ? "rotate(-45deg) translate(5px, -5px)" : "none" }}/>
            </button>
          </div>
        </div>

        {/* menu mobile drawer */}
        {menuOpen && (
          <div style={{ background:C.cream, borderTop:`1px solid ${C.muted}33`, padding:"16px 24px 20px" }} className="ng-mobile-menu">
            {["Início","Sobre","Instagram","TikTok"].map(n => (
              <a key={n} href="#" onClick={() => setMenuOpen(false)}
                style={{ display:"block", fontFamily:"'Syne',sans-serif", fontSize:15, fontWeight:600, color:C.navy, textDecoration:"none", padding:"11px 0", borderBottom:`1px solid ${C.muted}22`, letterSpacing:"0.04em" }}>
                {n}
              </a>
            ))}
            <div style={{ marginTop:14, display:"flex", alignItems:"center", gap:10, background:C.white, border:`1px solid ${C.muted}44`, padding:"9px 14px" }}>
              <input placeholder="Buscar..." style={{ border:"none", outline:"none", fontFamily:"'DM Sans',sans-serif", fontSize:14, background:"transparent", flex:1, color:C.navy }}/>
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={C.navy} strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
            </div>
          </div>
        )}

        {/* sub-nav categorias */}
        <div style={{ background:C.navy, overflowX:"auto" }}>
          <div style={{ maxWidth:1280, margin:"0 auto", padding:"0 24px", display:"flex", minWidth:"max-content" }}>
            {CATEGORIAS.map((n, i) => (
              <button key={n} onClick={() => setCatAtiva(i)}
                style={{ background:"none", border:"none", borderBottom: categoriaAtiva===i ? `2px solid ${C.orange}` : "2px solid transparent", color: categoriaAtiva===i ? C.orange : `${C.cream}bb`, fontFamily:"'Syne',sans-serif", fontSize:12, fontWeight:600, letterSpacing:"0.06em", padding:"11px 18px", cursor:"pointer", transition:"all .2s", whiteSpace:"nowrap" }}>
                {n}
              </button>
            ))}
          </div>
        </div>
      </header>

      <style>{`
        @media (max-width: 768px) {
          .ng-desktop-nav   { display: none !important; }
          .ng-desktop-search { display: none !important; }
          .ng-hamburger      { display: flex !important; }
        }
      `}</style>



      {/* ── MINI HERO com shapes (sem imagem, só tipografia) ── */}
      <section style={{ background:C.cream, padding:"52px 32px 48px", position:"relative", overflow:"hidden" }}>
        <svg style={{ position:"absolute", left:0, bottom:0, width:200, pointerEvents:"none" }} viewBox="0 0 200 200" fill="none">
          <path d="M40 200 L0 110 L70 70 L110 170 Z" fill={C.orange} opacity=".85"/>
          {[0,45,90,135,180,225,270,315].map(a=>(
            <ellipse key={a} cx="40" cy="165" rx="16" ry="7" fill={C.orange} opacity=".8" transform={`rotate(${a} 40 165)`}/>
          ))}
        </svg>
        <svg style={{ position:"absolute", right:0, top:0, width:120, pointerEvents:"none" }} viewBox="0 0 120 120" fill="none">
          <path d="M68 0 L120 0 L120 52 Z" fill={C.navy}/>
          <polygon points="90,64 108,46 120,64 108,82" fill={C.navy} opacity=".4"/>
        </svg>
        <div style={{ maxWidth:1280, margin:"0 auto", position:"relative", zIndex:2 }}>
          <h1 style={{ margin:0, lineHeight:1.05 }}>
            <span style={{ fontFamily:"'Caveat',cursive", fontSize:"clamp(42px,6vw,72px)", color:C.navy, fontStyle:"italic" }}>Visuais </span>
            <span style={{ fontFamily:"'Caveat',cursive", fontSize:"clamp(42px,6vw,72px)", color:C.orange, fontStyle:"italic" }}>brutal</span>
            <span style={{ fontFamily:"'Caveat',cursive", fontSize:"clamp(42px,6vw,72px)", color:C.orange }}>istas</span>
          </h1>
          <h2 style={{ margin:"2px 0 14px", lineHeight:1.1 }}>
            <span style={{ fontFamily:"'Syne',sans-serif", fontSize:"clamp(28px,4vw,52px)", fontWeight:800, color:C.navy }}>de </span>
            <span style={{ fontFamily:"'Caveat',cursive", fontSize:"clamp(28px,4vw,54px)", color:C.navy, fontStyle:"italic" }}>um </span>
            <span style={{ fontFamily:"'Syne',sans-serif", fontSize:"clamp(28px,4vw,52px)", fontWeight:800, color:C.navy }}>simples </span>
            <span style={{ fontFamily:"'Caveat',cursive", fontSize:"clamp(28px,4vw,54px)", color:C.orange }}>art</span>
            <span style={{ fontFamily:"'Syne',sans-serif", fontSize:"clamp(28px,4vw,52px)", fontWeight:800, color:C.navy }}>ista.</span>
          </h2>
          <p style={{ fontSize:14, color:`${C.navy}88`, letterSpacing:"0.12em", marginBottom:4 }}>Criativo &nbsp;–&nbsp; Autêntico &nbsp;–&nbsp; Independente</p>
          <p style={{ fontSize:14, fontStyle:"italic", color:`${C.navy}99`, marginBottom:28 }}>Por: Nandy Govi</p>
          <div style={{ display:"flex", gap:14, flexWrap:"wrap" }}>
            <a href="#produtos" style={{ background:C.orange, color:"#fff", padding:"13px 32px", textDecoration:"none", fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:700, letterSpacing:"0.1em", textTransform:"uppercase" }}>Ver coleção</a>
            <a href="#sobre" style={{ background:"transparent", color:C.navy, padding:"13px 32px", textDecoration:"none", fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:700, letterSpacing:"0.1em", textTransform:"uppercase", border:`2px solid ${C.navy}` }}>Sobre o artista</a>
          </div>
        </div>
      </section>

      {/* ═══ PRODUTOS EM DESTAQUE ═══ */}
      <section id="produtos" style={{ background:C.navy, padding:"56px 0" }}>
        <div style={{ maxWidth:1280, margin:"0 auto", padding:"0 32px" }}>
          <h2 style={{ fontFamily:"'Syne',sans-serif", fontSize:20, fontWeight:700, color:C.orange, textAlign:"center", letterSpacing:"0.08em", marginBottom:40, textTransform:"uppercase" }}>
            Produtos em destaque.
          </h2>
          {loadingProd ? (
            <div style={{ textAlign:"center", padding:"60px 0", color:`${C.cream}66`, fontFamily:"'DM Sans',sans-serif" }}>
              Carregando produtos...
            </div>
          ) : produtos.length === 0 ? (
            <div style={{ textAlign:"center", padding:"60px 0", color:`${C.cream}66`, fontFamily:"'DM Sans',sans-serif" }}>
              Nenhum produto disponível no momento.
            </div>
          ) : (
            <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(260px,1fr))", gap:22 }}>
              {produtos.map(p => <ProductCard key={p.id} produto={p} onBuy={() => openModal(p)} />)}
            </div>
          )}
        </div>
      </section>

      {/* ═══ BANNER DO ARTISTA — imagem real, logo abaixo dos produtos ═══ */}
      <section id="sobre" style={{ background:C.cream, lineHeight:0 }}>
        <img
          src={IMG_BANNER}
          alt="Nandy Govi — Visuais brutalistas de um simples artista"
          style={{ display:"block", width:"100%", height:"auto" }}
        />
      </section>

      {/* FOOTER laranja */}
      <footer style={{ background:C.orange, padding:"28px 32px", textAlign:"center" }}>
        <div style={{ display:"flex", justifyContent:"center", gap:20, marginBottom:14 }}>
          {[
            { href:"https://instagram.com/nandygovi", icon:<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="1.8"><rect x="2" y="2" width="20" height="20" rx="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg> },
            { href:"https://www.tiktok.com/@nandy.govi", icon:<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="1.8"><path d="M9 12a4 4 0 1 0 4 4V4a5 5 0 0 0 5 5"/></svg> },
          ].map((s,i) => (
            <a key={i} href={s.href} target="_blank" rel="noreferrer"
              style={{ width:38, height:38, border:"1.5px solid rgba(255,255,255,.5)", borderRadius:"50%", display:"flex", alignItems:"center", justifyContent:"center", transition:"background .2s" }}
              onMouseOver={e=>e.currentTarget.style.background="rgba(255,255,255,0.22)"}
              onMouseOut={e=>e.currentTarget.style.background="transparent"}>{s.icon}</a>
          ))}
        </div>
        <p style={{ fontSize:12, color:"rgba(255,255,255,0.82)", letterSpacing:"0.04em" }}>
          Copyright Nandy Govi – 62772634000110 – 2026. Todos os direitos reservados.
        </p>
      </footer>

      {/* ═══ MODAL PRODUTO ═══ */}
      {modal && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,.78)", zIndex:200, display:"flex", alignItems:"center", justifyContent:"center", padding:16 }}
          onClick={e => { if(e.target===e.currentTarget) setModal(null); }}>
          <div style={{ background:"#fff", width:"100%", maxWidth:780, maxHeight:"92vh", overflowY:"auto", display:"flex", flexDirection:"column" }}>

            {/* header modal */}
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"16px 20px", borderBottom:"1px solid #eee", flexShrink:0 }}>
              <h3 style={{ fontFamily:"'Syne',sans-serif", fontSize:16, fontWeight:700, color:C.navy, margin:0 }}>{modal.titulo}</h3>
              <button onClick={()=>setModal(null)} style={{ background:"none", border:"none", cursor:"pointer", fontSize:26, color:C.muted, lineHeight:1, flexShrink:0 }}>×</button>
            </div>

            {/* body — empilha em mobile */}
            <div style={{ display:"flex", flexDirection:"row", flexWrap:"wrap" }}>
              {/* preview imagem */}
              <div style={{ width:"clamp(120px,35%,260px)", flexShrink:0, background:modal.bg || C.navy, display:"flex", alignItems:"center", justifyContent:"center", minHeight:220 }}>
                {modal.imagem_url
                  ? <img src={modal.imagem_url} alt={modal.titulo} style={{ width:"100%", height:"100%", objectFit:"cover", display:"block" }}/>
                  : <span style={{ fontSize:72 }}>{modal.emoji || "🖼️"}</span>}
              </div>

              {/* opções */}
              <div style={{ flex:1, minWidth:240, padding:"20px clamp(14px,3vw,24px)", overflowY:"auto" }}>
                {modal.descricao && <p style={{ fontSize:12, color:C.muted, marginBottom:8 }}>{modal.descricao}</p>}
                <p style={{ fontFamily:"'Syne',sans-serif", fontSize:22, fontWeight:700, color:C.navy, marginBottom:20 }}>
                  {fmt(modalPreco)}
                </p>

                {/* tamanho */}
                <p style={{ fontSize:11, fontWeight:700, letterSpacing:"0.1em", textTransform:"uppercase", color:C.navy, marginBottom:8 }}>Tamanho</p>
                <div style={{ display:"flex", gap:8, marginBottom:20, flexWrap:"wrap" }}>
                  {TAMANHOS.map(t => (
                    <button key={t.id} onClick={() => setTamanho(t.id)}
                      style={{ padding:"8px 12px", border:`2px solid ${tamanho===t.id?C.navy:"#e0e0e0"}`, background:tamanho===t.id?C.navy:"transparent", color:tamanho===t.id?"#fff":C.navy, fontFamily:"'Syne',sans-serif", fontSize:11, fontWeight:700, cursor:"pointer", textAlign:"center", transition:"all .15s" }}>
                      <div>{t.label}</div>
                      <div style={{ fontSize:10, opacity:.65, fontWeight:400 }}>{t.desc}</div>
                    </button>
                  ))}
                </div>

                {/* tipo de quadro */}
                <p style={{ fontSize:11, fontWeight:700, letterSpacing:"0.1em", textTransform:"uppercase", color:C.navy, marginBottom:8 }}>Tipo do quadro</p>
                <div style={{ display:"flex", flexDirection:"column", gap:6, marginBottom:20 }}>
                  {OPCOES_QUADRO.map(op => (
                    <button key={op.id} onClick={() => setOpcao(op.id)}
                      style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"10px 12px", border:`2px solid ${opcao===op.id?C.orange:"#e0e0e0"}`, background:opcao===op.id?`${C.orange}14`:"transparent", cursor:"pointer", textAlign:"left", transition:"all .15s" }}>
                      <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                        <div style={{ width:14, height:14, borderRadius:"50%", border:`2px solid ${opcao===op.id?C.orange:"#bbb"}`, background:opcao===op.id?C.orange:"transparent", flexShrink:0 }}/>
                        <div>
                          <div style={{ fontFamily:"'Syne',sans-serif", fontSize:12, fontWeight:700, color:C.navy }}>{op.label}</div>
                          <div style={{ fontSize:11, color:C.muted }}>{op.desc}</div>
                        </div>
                      </div>
                      <span style={{ fontSize:12, fontWeight:700, color:op.extra===0?C.muted:C.orange, flexShrink:0, marginLeft:8 }}>
                        {op.extra===0 ? "Incluso" : `+${fmt(op.extra)}`}
                      </span>
                    </button>
                  ))}
                </div>

                {/* nota pix */}
                <div style={{ background:`${C.navy}0d`, border:`1px solid ${C.navy}20`, padding:"10px 12px", marginBottom:16, display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontSize:16 }}>⚡</span>
                  <span style={{ fontSize:12, color:C.navy }}>Pagamento <strong>exclusivo via Pix</strong> · Aprovação imediata</span>
                </div>

                <button onClick={() => addToCart(modal, opcao, tamanho)}
                  style={{ width:"100%", background:C.orange, color:"#fff", border:"none", padding:"14px", fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:700, letterSpacing:"0.08em", textTransform:"uppercase", cursor:"pointer" }}
                  onMouseOver={e=>e.currentTarget.style.background="#c96e1a"}
                  onMouseOut={e=>e.currentTarget.style.background=C.orange}>
                  Adicionar ao carrinho
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ═══ CARRINHO DRAWER ═══ */}
      {cartOpen && (
        <div style={{ position:"fixed", inset:0, background:"rgba(0,0,0,.58)", zIndex:200 }}
          onClick={e=>{ if(e.target===e.currentTarget) setCartOpen(false); }}>
          <div style={{ position:"absolute", top:0, right:0, bottom:0, width:410, background:"#fff", display:"flex", flexDirection:"column" }}>
            <div style={{ padding:"20px 24px", borderBottom:"1px solid #eee", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
              <h3 style={{ fontFamily:"'Syne',sans-serif", fontSize:17, fontWeight:700, color:C.navy }}>Meu Carrinho</h3>
              <button onClick={()=>setCartOpen(false)} style={{ background:"none", border:"none", cursor:"pointer", fontSize:26, color:C.muted }}>×</button>
            </div>

            <div style={{ flex:1, overflowY:"auto", padding:24 }}>
              {cart.length===0 ? (
                <div style={{ textAlign:"center", paddingTop:60 }}>
                  <div style={{ fontSize:52, marginBottom:14 }}>🛒</div>
                  <p style={{ fontFamily:"'Syne',sans-serif", fontSize:15, fontWeight:600, color:C.navy }}>Carrinho vazio</p>
                  <p style={{ fontSize:12, color:C.muted, marginTop:4 }}>Adicione produtos para continuar</p>
                </div>
              ) : cart.map(item => (
                <div key={item.key} style={{ display:"flex", gap:14, marginBottom:18, paddingBottom:18, borderBottom:"1px solid #eee" }}>
                  <div style={{ width:70, height:88, background:item.produto.bg, flexShrink:0, display:"flex", alignItems:"center", justifyContent:"center", fontSize:30 }}>{item.produto.emoji}</div>
                  <div style={{ flex:1 }}>
                    <p style={{ fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:600, color:C.navy, marginBottom:2 }}>{item.produto.titulo}</p>
                    <p style={{ fontSize:11, color:C.muted, marginBottom:8 }}>{item.tam.desc} · {item.opc.label}</p>
                    <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                      <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                        <button onClick={()=>changeQty(item.key,-1)} style={qtyBtn()}>−</button>
                        <span style={{ fontSize:13, fontWeight:600, minWidth:22, textAlign:"center" }}>{item.qty}</span>
                        <button onClick={()=>changeQty(item.key,1)} style={qtyBtn()}>+</button>
                      </div>
                      <span style={{ fontSize:14, fontWeight:700, color:C.navy }}>{fmt(item.preco*item.qty)}</span>
                    </div>
                    <button onClick={()=>removeItem(item.key)} style={{ background:"none", border:"none", cursor:"pointer", fontSize:11, color:C.muted, textDecoration:"underline", marginTop:5, fontFamily:"'DM Sans',sans-serif" }}>Remover</button>
                  </div>
                </div>
              ))}
            </div>

            {cart.length>0 && (
              <div style={{ padding:24, borderTop:"1px solid #eee" }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
                  <span style={{ fontSize:14, color:C.muted }}>Total</span>
                  <span style={{ fontFamily:"'Syne',sans-serif", fontSize:20, fontWeight:700, color:C.navy }}>{fmt(cartTotal)}</span>
                </div>
                <button
                  onClick={() => {
                    if (!usuario) {
                      setCartOpen(false);
                      onIrCadastro?.();
                      return;
                    }
                    setCartOpen(false);
                    onCheckout?.(cart);
                  }}
                  style={{ width:"100%", background:usuario ? C.navy : C.muted, color:"#fff", border:"none", padding:15, fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:700, letterSpacing:"0.08em", textTransform:"uppercase", cursor:"pointer" }}
                  onMouseOver={e => e.currentTarget.style.background = usuario ? C.orange : C.muted}
                  onMouseOut={e => e.currentTarget.style.background = usuario ? C.navy : C.muted}>
                  {usuario ? "Finalizar com Pix ⚡" : "Entrar para finalizar →"}
                </button>
                {!usuario && (
                  <p style={{ textAlign:"center", fontSize:11, color:C.orange, marginTop:8, fontWeight:600 }}>
                    Faça login ou crie uma conta para continuar
                  </p>
                )}
                <p style={{ textAlign:"center", fontSize:11, color:C.muted, marginTop:10 }}>Pagamento exclusivo via Pix · Aprovação imediata</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* TOAST */}
      {toast && (
        <div style={{ position:"fixed", bottom:28, left:"50%", transform:"translateX(-50%)", background:C.navy, color:"#fff", padding:"13px 22px", fontSize:13, zIndex:300, display:"flex", alignItems:"center", gap:10, boxShadow:"0 4px 20px rgba(0,0,0,.3)", whiteSpace:"nowrap" }}>
          <span style={{ color:"#6BCB77" }}>✓</span> {toast}
        </div>
      )}
    </div>
  );
}

/* ── PRODUCT CARD ─────────────────────────────────────────────── */
function ProductCard({ produto, onBuy }) {
  const [hov, setHov] = useState(false);
  const f = v => Number(v||0).toLocaleString("pt-BR", { style:"currency", currency:"BRL" });
  const bg = produto.bg || "#1B2E4B";
  return (
    <div onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{ background:"#fff", cursor:"pointer", transform:hov?"translateY(-5px)":"translateY(0)", transition:"transform .25s, box-shadow .25s", boxShadow:hov?"0 14px 36px rgba(0,0,0,.28)":"0 2px 10px rgba(0,0,0,.18)" }}>
      <div style={{ position:"relative", aspectRatio:"3/4", background:bg, display:"flex", alignItems:"center", justifyContent:"center", overflow:"hidden" }}>
        {produto.imagem_url
          ? <img src={produto.imagem_url} alt={produto.titulo} style={{ width:"100%", height:"100%", objectFit:"cover", display:"block" }}/>
          : <span style={{ fontSize:78, filter:"drop-shadow(0 4px 14px rgba(0,0,0,.45))" }}>{produto.emoji || "🖼️"}</span>
        }
        <div style={{ position:"absolute", inset:0, background:`linear-gradient(to top, ${bg}90, transparent 55%)` }}/>
        <button onClick={onBuy} style={{ position:"absolute", bottom:0, left:0, right:0, background:hov?"rgba(27,46,75,.96)":"rgba(27,46,75,0)", color:"#fff", border:"none", padding:"13px", fontFamily:"'Syne',sans-serif", fontSize:11, fontWeight:700, letterSpacing:"0.1em", textTransform:"uppercase", cursor:"pointer", transition:"all .25s", opacity:hov?1:0, transform:hov?"translateY(0)":"translateY(8px)" }}>
          Escolher opções
        </button>
      </div>
      <div style={{ padding:"13px 15px 15px", background:"#fff" }}>
        <p style={{ fontFamily:"'Syne',sans-serif", fontSize:13, fontWeight:600, color:C.navy, marginBottom:2, lineHeight:1.35 }}>{produto.titulo}</p>
        {produto.subtitulo && <p style={{ fontSize:11, color:C.muted, marginBottom:10 }}>{produto.subtitulo}</p>}
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
          <span style={{ fontFamily:"'Syne',sans-serif", fontSize:16, fontWeight:700, color:C.navy }}>{f(produto.preco_base || produto.preco || 0)}</span>
          <button onClick={onBuy} style={{ background:C.orange, color:"#fff", border:"none", padding:"7px 14px", fontFamily:"'Syne',sans-serif", fontSize:11, fontWeight:700, letterSpacing:"0.05em", cursor:"pointer", textTransform:"uppercase", display:"flex", alignItems:"center", gap:5 }}>
            Comprar
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
          </button>
        </div>
      </div>
    </div>
  );
}
